// src/pages/HomePage.js
import React, { useEffect, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import axios from 'axios';

function HomePage() {
    const [categories, setCategories] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [isTreeVisible, setIsTreeVisible] = useState(false);
    const [selectedCategory, setSelectedCategory] = useState(null);
    const timerRef = useRef(null);
    const buttonRef = useRef(null);

    useEffect(() => {
        const fetchCategories = async () => {
            try {
                const response = await axios.get('http://localhost:8080/category');
                setCategories(response.data);
            } catch (err) {
                setError(err);
            } finally {
                setLoading(false);
            }
        };
        fetchCategories();
    }, []);

    const showTreeWithDelay = () => {
        if (timerRef.current) {
            clearTimeout(timerRef.current);
        }
        timerRef.current = setTimeout(() => {
            setIsTreeVisible(true);
        }, 300);
    };

    const hideTreeWithDelay = () => {
        if (timerRef.current) {
            clearTimeout(timerRef.current);
        }
        timerRef.current = setTimeout(() => {
            setIsTreeVisible(false);
            setSelectedCategory(null);
        }, 100);
    };

    const handleCategorySelect = (category) => {
        setSelectedCategory(category);
    };

    // A recursive function to render categories as clickable links
    const renderCategoryLinks = (category, level = 0) => (
        <React.Fragment key={category.id}>
            <Link
                to={`/products/${category.id}`}
                onMouseEnter={() => handleCategorySelect(category)}
                style={{
                    display: 'block',
                    textDecoration: 'none',
                    color: 'inherit',
                    padding: '10px',
                    paddingLeft: `${15 + level * 20}px`, // Indent subcategories
                    cursor: 'pointer',
                    backgroundColor: selectedCategory && selectedCategory.id === category.id ? '#f0f0f0' : 'transparent',
                    whiteSpace: 'nowrap',
                    overflow: 'hidden',
                    textOverflow: 'ellipsis'
                }}>
                {category.name}
            </Link>
            {category.children && category.children.length > 0 && (
                <div style={{ marginLeft: '10px' }}>
                    {category.children.map(child => renderCategoryLinks(child, level + 1))}
                </div>
            )}
        </React.Fragment>
    );

    if (loading) {
        return <div>Loading...</div>;
    }

    if (error) {
        return <div>Error: {error.message}</div>;
    }

    // Filter for top-level categories (with parentId null or undefined)
    const topLevelCategories = categories.filter(cat => !cat.parentId);

    return (
        <div style={{ padding: '20px', fontFamily: 'sans-serif' }}>
            <h1>E-Shop Categories</h1>
            <div style={{ position: 'relative', display: 'inline-block' }}>
                <button
                    ref={buttonRef}
                    onMouseEnter={showTreeWithDelay}
                    onMouseLeave={hideTreeWithDelay}
                    style={{
                        padding: '10px 20px',
                        fontSize: '18px',
                        backgroundColor: '#007bff',
                        color: 'white',
                        border: 'none',
                        borderRadius: '5px',
                        cursor: 'pointer',
                        whiteSpace: 'nowrap'
                    }}>
                    {isTreeVisible ? '▼ ' : '▶ '}
                    Kategorijos
                </button>
                {isTreeVisible && (
                    <div
                        onMouseEnter={showTreeWithDelay}
                        onMouseLeave={hideTreeWithDelay}
                        style={{
                            position: 'absolute',
                            top: '100%',
                            left: '0',
                            width: selectedCategory ? '800px' : '250px',
                            backgroundColor: 'white',
                            border: '1px solid #ccc',
                            boxShadow: '0 4px 8px rgba(0, 0, 0, 0.2)',
                            zIndex: 1000,
                            display: 'flex',
                            flexDirection: 'row',
                            padding: '5px',
                            transition: 'width 0.3s ease-in-out'
                        }}>
                        {/* Left Sidebar - Renders all clickable links */}
                        <div style={{ width: '250px', borderRight: '1px solid #eee', paddingRight: '10px' }}>
                            {topLevelCategories.map(cat => renderCategoryLinks(cat))}
                        </div>
                        {/* Right Content Area - Conditionally rendered */}
                        {selectedCategory && (
                            <div style={{ width: '550px', paddingLeft: '20px' }}>
                                {selectedCategory.children && selectedCategory.children.length > 0 ? (
                                    selectedCategory.children.map(child => (
                                        <div key={child.id} style={{ marginBottom: '15px' }}>
                                            <h4>{child.name}</h4>
                                            {child.children && child.children.length > 0 && (
                                                <div style={{ display: 'flex', flexDirection: 'column' }}>
                                                    {child.children.map(subChild => (
                                                        <span key={subChild.id} style={{ fontSize: '14px', color: '#555' }}>
                                                            {subChild.name}
                                                        </span>
                                                    ))}
                                                </div>
                                            )}
                                        </div>
                                    ))
                                ) : (
                                    <div>No subcategories available.</div>
                                )}
                            </div>
                        )}
                    </div>
                )}
            </div>
        </div>
    );
}

export default HomePage;
